import struct

"""
https://www.color.org/specification/ICC1v43_2010-12.pdf
"""
def read_tag_table(icc_bytes):
    tags = {}

    if len(icc_bytes) < 132:
        raise ValueError("Invalid ICC profile: Too short.")

    # 태그 개수
    tag_count = struct.unpack(">I", icc_bytes[128:132])[0]

    # 태그 테이블 파싱
    for i in range(tag_count):
        entry_offset = 132 + i * 12
        tag_sig = icc_bytes[entry_offset:entry_offset + 4].decode("ascii", errors="ignore")
        tag_data_offset = struct.unpack(">I", icc_bytes[entry_offset + 4:entry_offset + 8])[0]
        tag_data_size = struct.unpack(">I", icc_bytes[entry_offset + 8:entry_offset + 12])[0]
        tag_data = icc_bytes[tag_data_offset:tag_data_offset + tag_data_size]
        tags[tag_sig] = tag_data
    return tags


def decode_tag(tag_sig, tag_data):
    tag_type = tag_data[:4].decode("ascii", errors="ignore")

    if tag_type == "desc":
        # ICC desc type: type (4) + reserved (4) + string length (4) + string
        text_len = struct.unpack(">I", tag_data[8:12])[0]
        text = tag_data[12:12 + text_len].decode("utf-8", errors="ignore").strip("\x00")
        return text

    elif tag_type == "text":
        # Legacy plain text
        return tag_data[8:].decode("ascii", errors="ignore").strip("\x00")

    elif tag_type == "mluc":
        # Multi-localized Unicode (mluc)
        return decode_mluc(tag_data)

    elif tag_type == "XYZ ":
        # XYZ type
        return decode_xyz(tag_data)

    elif tag_type == "sf32":
        # 32-bit signed float (parametric curve etc.)
        return f"<{tag_type} - {len(tag_data)} bytes>"

    elif tag_type == "para":
        # Parametric curve
        return f"<{tag_type} - {len(tag_data)} bytes>"

    else:
        return f"<{tag_type} - {len(tag_data)} bytes>"

def decode_mluc(data):
    try:
        # Skip first 8 bytes (type + reserved)
        count = struct.unpack(">I", data[8:12])[0]
        rec_size = struct.unpack(">I", data[12:16])[0]
        records = []
        for i in range(count):
            offset = 16 + i * rec_size
            lang = data[offset:offset+2].decode("ascii")
            country = data[offset+2:offset+4].decode("ascii")
            str_len = struct.unpack(">I", data[offset+4:offset+8])[0]
            str_offset = struct.unpack(">I", data[offset+8:offset+12])[0]
            string = data[str_offset:str_offset + str_len].decode("utf-16-be", errors="ignore").strip("\x00")
            records.append(f"{lang}-{country}: {string}")
        return records
    except Exception as e:
        return f"<mluc decode error: {e}>"

def decode_xyz(data):
    # XYZ type: 4 byte type + 4 byte reserved + 3 x 4-byte s15Fixed16Number
    def fixed_to_float(b):
        val = struct.unpack(">i", b)[0]
        return val / 65536.0

    if len(data) < 20:
        return "<invalid XYZ>"

    x = fixed_to_float(data[8:12])
    y = fixed_to_float(data[12:16])
    z = fixed_to_float(data[16:20])
    return f"X={x:.4f}, Y={y:.4f}, Z={z:.4f}"


def parse_icc_bytes(icc_bytes):
    tags = read_tag_table(icc_bytes)
    parsed = {}

    for tag_sig, tag_data in tags.items():
        parsed[tag_sig] = decode_tag(tag_sig, tag_data)

    return parsed

